id, sname, sex, birthday, sid,
depart_id, post_id, entrydate, joinworkdate, workform, staffsource,
politicalstatus, nation, nativeplace, stel, semail, skill_tags, sheight,
bloodtype, maritalstatus, registeredresidence, education, degree, university,
major, graduationdate, startdate, enddate, status, peroidopdate, user_id
) values (
null, #{sname}, #{sex}, #{birthday}, #{sid},
#{depart_id}, #{post_id}, #{entrydate}, #{joinworkdate}, #{workform}, #{staffsource},
#{politicalstatus}, #{nation}, #{nativeplace}, #{stel}, #{semail}, #{skill_tags}, #{sheight},
#{bloodtype}, #{maritalstatus}, #{registeredresidence}, #{education}, #{degree}, #{university},
#{major}, #{graduationdate}, #{startdate}, #{enddate}

    , '正常'


    , #{status}

, #{peroidopdate}, #{user_id}
)

mapper.select:
select * from hr_employee s, sys_department d, sys_post p where s.depart_id = d.id and s.post_id = p.id

    and s.sname like concat('%',#{sname},'%')


    and s.depart_id = #{depart_id}


    limit #{startIndex}, #{pageSize}

mapper.update:
update hr_employee
sname = #{sname}, sex = #{sex}, birthday = #{birthday}, sid = #{sid}, depart_id = #{depart_id}, post_id = #{post_id}, entrydate = #{entrydate}, joinworkdate = #{joinworkdate}, workform = #{workform}, staffsource = #{staffsource}, politicalstatus = #{politicalstatus}, nation = #{nation}, nativeplace = #{nativeplace}, stel = #{stel}, semail = #{semail}, skill_tags = #{skill_tags}, sheight = #{sheight}, bloodtype = #{bloodtype}, maritalstatus = #{maritalstatus}, registeredresidence = #{registeredresidence}, education = #{education}, degree = #{degree}, university = #{university}, major = #{major}, graduationdate = #{graduationdate}, startdate = #{startdate}, enddate = #{enddate} , user_id = #{user_id}
where id = #{id}

mapper.select:
select s.id, s.sname, s.sex, s.birthday, s.sid, s.depart_id, s.post_id, s.entrydate, s.joinworkdate,
       s.workform, s.staffsource, s.politicalstatus, s.nation, s.nativeplace, s.stel, s.semail,
       s.skill_tags, s.sheight, s.bloodtype, s.maritalstatus, s.registeredresidence, s.education,
       s.degree, s.university, s.major, s.graduationdate, s.startdate, s.enddate, s.peroidopdate,
       COALESCE(s.status, '正常') as status, s.user_id,
       d.dname, p.pname,
       DATE_FORMAT(s.startdate,'%Y-%m-%d') as startdate1,
       DATE_FORMAT(s.enddate,'%Y-%m-%d') as enddate1
from hr_employee s
left join sys_department d on s.depart_id = d.id
left join sys_post p on s.post_id = p.id
where ((s.startdate IS NOT NULL or s.enddate IS NOT NULL)
   or (s.status IS NOT NULL and s.status != '正常'))

    and s.sname like concat('%',#{sname},'%')


    and s.depart_id = #{depart_id}


    and s.post_id = #{post_id}


    and COALESCE(s.status, '正常') = #{status}


    and s.startdate >= #{startdate}


    and s.enddate <= #{enddate}


    limit #{startIndex}, #{pageSize}

mapper.update:
update hr_employee
status = #{status}, peroidopdate = now()
where id=#{id}

update hr_employee
enddate = #{enddate}, status = '转正', peroidopdate = now()
where id=#{id}

mapper.select:
select t.id, t.staff_id, t.sname, t.ttype, t.beforepost_id, t.afterpost_id, COALESCE(bp.pname, '未知岗位') as beforepost_name, COALESCE(ap.pname, '未知岗位') as afterpost_name, DATE_FORMAT(t.tdate,'%Y-%m-%d') as tdate1, DATE_FORMAT(t.opdate,'%Y-%m-%d') as opdate1 from transfer t left join sys_post bp on t.beforepost_id = bp.id left join sys_post ap on t.afterpost_id = ap.id where 1=1
and t.sname like concat('%',#{sname},'%')
and t.staff_id = #{staff_id}
and t.ttype = #{ttype}
and date(t.tdate) between #{startdate} and #{enddate}
order by t.tdate desc, t.opdate desc
limit #{startIndex}, #{pageSize}
